// The single runtime deployment configuration. Everything about addresses, chain, ABIs and public
// RPC endpoints is read from dist/imd-deployment.json (generated by scripts/manifest.mjs from the
// deployment handoff). Nothing in the bundle duplicates it.
import type { Abi, Address } from 'viem';

export interface PoolKey {
  currency0: Address;
  currency1: Address;
  fee: number;
  tickSpacing: number;
  hooks: Address;
}

export interface NetworkBlock {
  chainId: number;
  name: string;
  testnet: boolean;
  rpcUrls: string[];
  explorer: string;
  nativeCurrency: { name: string; symbol: string; decimals: number };
  faucets: string[];
  uniswapV4: {
    poolManager: Address;
    universalRouter: Address;
    quoter: Address;
    stateView: Address;
    positionManager: Address;
    permit2: Address;
    extendedSwapParams?: boolean;
  };
  pairToken: { address: Address; symbol: string; name: string; decimals: number };
  otherPairTokens?: { id: string; address: Address; symbol: string; name: string; decimals: number }[];
}

export interface WalletAddChain {
  chainId: string;
  chainName: string;
  rpcUrls: string[];
  nativeCurrency: { name: string; symbol: string; decimals: number };
  blockExplorerUrls: string[];
}

export interface DeploymentManifest {
  version: 1;
  launchId: string;
  chainId: number;
  sourceCommit: string;
  attestationHash: string;
  contracts: { name: string; address: Address; abiHash: string; abiPath: string }[];
  assets: { path: string; sha256: string }[];
  poolKey?: PoolKey;
  network?: NetworkBlock;
  walletAddChain?: WalletAddChain;
}

export interface AppConfig {
  manifest: DeploymentManifest;
  chainId: number;
  network: NetworkBlock | null;
  walletAddChain: WalletAddChain | null;
  poolKey: PoolKey | null;
  token: { address: Address; abi: Abi };
  frontPage: { address: Address; abi: Abi };
  explorer: string;
}

export const MANIFEST_PATH = './imd-deployment.json';

export async function loadConfig(fetchImpl: typeof fetch = fetch): Promise<AppConfig> {
  const res = await fetchImpl(MANIFEST_PATH, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`Could not load ${MANIFEST_PATH} (${res.status})`);
  const manifest = (await res.json()) as DeploymentManifest;
  if (manifest.version !== 1 || !Array.isArray(manifest.contracts)) {
    throw new Error('imd-deployment.json has an unexpected shape');
  }
  const find = (name: string) => {
    const c = manifest.contracts.find((x) => x.name === name);
    if (!c) throw new Error(`imd-deployment.json lists no contract named ${name}`);
    return c;
  };
  const token = find('LaunchToken');
  const frontPage = find('ScoopFrontPage');
  const loadAbi = async (p: string): Promise<Abi> => {
    const r = await fetchImpl('./' + p, { cache: 'no-cache' });
    if (!r.ok) throw new Error(`Could not load ABI ${p} (${r.status})`);
    return (await r.json()) as Abi;
  };
  const [tokenAbi, frontAbi] = await Promise.all([loadAbi(token.abiPath), loadAbi(frontPage.abiPath)]);
  const network = manifest.network ?? null;
  return {
    manifest,
    chainId: manifest.chainId,
    network,
    walletAddChain: manifest.walletAddChain ?? null,
    poolKey: manifest.poolKey ?? null,
    token: { address: token.address, abi: tokenAbi },
    frontPage: { address: frontPage.address, abi: frontAbi },
    explorer: network?.explorer ?? '',
  };
}
